SELECT
  `__mb_source`.`name` AS `name`,
  CAST(
    AVG(`__mb_source`.`Staff Onboarding Qn. 1`) + AVG(`__mb_source`.`Staff Onboarding Qn. 5`) AS double
  ) / 2.0 AS `Staff Onboarding Average (Obj. 5)`,
  CAST(
    AVG(`__mb_source`.`Staff Survey Qn. 7`) + AVG(`__mb_source`.`Staff Survey Qn. 12`) AS double
  ) / 2.0 AS `Staff Survey Average (Obj.5)`,
  CAST(
    AVG(`__mb_source`.`Exit  Qn. 7`) + AVG(`__mb_source`.`Exit Qn.12`) AS double
  ) / 2.0 AS `Exit Average (Obj.5)`
FROM
  (
    SELECT
      `TabStaff Onboarding Survey - Survey Entry`.`qn_1` * 5 AS `Staff Onboarding Qn. 1`,
      `TabStaff Onboarding Survey - Survey Entry`.`qn_5` * 5 AS `Staff Onboarding Qn. 5`,
      `TabStaff Survey - Survey Entry`.`rating_7` * 5 AS `Staff Survey Qn. 7`,
      `TabStaff Survey - Survey Entry`.`rating_12` * 5 AS `Staff Survey Qn. 12`,
      `TabExit Interview Survey - Survey Entry`.`rate_7` * 5 AS `Exit  Qn. 7`,
      `TabExit Interview Survey - Survey Entry`.`rate_12` * 5 AS `Exit Qn.12`,
      `__mb_source`.`name` AS `name`
    FROM
      (
        select
          *
        from
          `tabSurvey Tracking`
      ) AS `__mb_source`
      LEFT JOIN (
        SELECT
          `tabSurvey Tracking List of Surveys Childtable`.`name` AS `name`,
          `tabSurvey Tracking List of Surveys Childtable`.`creation` AS `creation`,
          `tabSurvey Tracking List of Surveys Childtable`.`modified` AS `modified`,
          `tabSurvey Tracking List of Surveys Childtable`.`modified_by` AS `modified_by`,
          `tabSurvey Tracking List of Surveys Childtable`.`owner` AS `owner`,
          `tabSurvey Tracking List of Surveys Childtable`.`docstatus` AS `docstatus`,
          `tabSurvey Tracking List of Surveys Childtable`.`idx` AS `idx`,
          `tabSurvey Tracking List of Surveys Childtable`.`parent` AS `parent`,
          `tabSurvey Tracking List of Surveys Childtable`.`parentfield` AS `parentfield`,
          `tabSurvey Tracking List of Surveys Childtable`.`parenttype` AS `parenttype`,
          `tabSurvey Tracking List of Surveys Childtable`.`type_of_survey` AS `type_of_survey`,
          `tabSurvey Tracking List of Surveys Childtable`.`survey_entry` AS `survey_entry`,
          `tabSurvey Tracking List of Surveys Childtable`.`notes` AS `notes`,
          `tabSurvey Tracking List of Surveys Childtable`.`survey_response` AS `survey_response`
        FROM
          `tabSurvey Tracking List of Surveys Childtable`
      ) AS `TabSurvey Tracking List Of Surveys Childtable - name` ON `__mb_source`.`name` = `TabSurvey Tracking List Of Surveys Childtable - name`.`parent`
      LEFT JOIN (
        SELECT
          `tabExit Interview Survey`.`name` AS `name`,
          `tabExit Interview Survey`.`creation` AS `creation`,
          `tabExit Interview Survey`.`modified` AS `modified`,
          `tabExit Interview Survey`.`modified_by` AS `modified_by`,
